const ALL = ['HCC', 'iCCA', 'HB'] as const;
export const JOURNEY: JourneyStep[] = [
  { id: 'surveillance', subtypes: ['HCC'], title: 'Watching a liver at risk', plain: 'If you have cirrhosis or some types of hepatitis B, an ultrasound every 6 months (often with an AFP blood test) can catch cancer early, when cure is most likely.', clinician: 'AGA 2026: US ± AFP q6mo for cirrhosis; HBV per PAGE-B/REAL-B; not for non-cirrhotic MASLD or cured HCV without cirrhosis.', questions: ['Do I need liver cancer surveillance, and how often?', 'Should my AFP be checked too?'] },
  { id: 'diagnosis', subtypes: [...ALL], title: 'Getting a clear diagnosis', plain: 'Special CT or MRI scans can often confirm liver cancer without a needle sample. Sometimes a small sample (biopsy) is still needed.', plainBy: { iCCA: 'A small sample of the tumor (biopsy) is needed to confirm bile-duct cancer. The same sample is used for gene testing, so ask that enough tissue is taken.', HB: 'Scans and a very high AFP blood level usually point to hepatoblastoma. A biopsy is often taken to confirm it and plan treatment.' }, clinician: 'LI-RADS imaging for HCC in at-risk patients; biopsy for iCCA and atypical lesions; HB diagnosis with AFP and imaging, biopsy per protocol.', questions: ['Was the diagnosis made by scan or biopsy?', 'Is there enough tissue for gene testing?'] },
  { id: 'stage-hcc', subtypes: ['HCC'], title: 'Understanding the stage (BCLC)', plain: 'Doctors use the BCLC system, which looks at tumor size and number, how well the liver works (Child-Pugh), and how you feel day to day. Stage 0/A: often curable. B: treated inside the liver. C: medicines for the whole body. D: comfort-focused care.', clinician: 'BCLC 2022: 0/A >5 y median survival; B ~2.5 y; C ~2 y; D ~3 mo. Use Child-Pugh/ALBI, ECOG; consider treatment-stage migration.', questions: ['What is my BCLC stage and Child-Pugh score?', 'Am I a candidate for transplant or surgery now — or later?'] },
  { id: 'stage-hb', subtypes: ['HB'], title: 'Understanding the stage (PRETEXT)', plain: 'PRETEXT (I–IV) describes how much of the liver the tumor involves. Together with age and AFP, it places your child in a risk group that guides treatment.', clinician: 'PRETEXT I–IV with annotation factors; CHIC risk stratification (validated 2025 across SIOPEL-4/6, AHEP0731, JPLT-2).', questions: ['What is my child’s PRETEXT stage and risk group?', 'Will surgery happen after chemotherapy?'] },
  { id: 'molecular', subtypes: ['iCCA', 'HCC'], title: 'Testing the tumor’s genes', plain: 'A full gene test of the tumor (NGS) can find changes like FGFR2, IDH1, HER2 or BRAF that have matched medicines.', plainBy: { iCCA: 'A full gene test of the tumor (NGS) is recommended for advanced bile-duct cancer. It can find changes like FGFR2, IDH1, HER2 or BRAF that have matched medicines.', HCC: 'For liver-cell cancer, gene testing rarely changes treatment today. One blood test does matter: a very high AFP (400 or more) opens an extra treatment option later.' }, clinician: 'ESMO: multigene NGS for advanced iCCA, RNA-based for fusions; FGFR2 fusions ~9–13%, IDH1 ~14–29%, BRAF V600E ~5%, HER2 1.6–4%, MSI-H ~1.2%.', questions: ['Has my tumor had comprehensive gene testing (NGS)?', 'Did it include RNA testing for fusions?'] },
  { id: 'mdt', subtypes: [...ALL], title: 'The tumor board decides together', plain: 'A team of surgeons, liver doctors, cancer doctors and radiologists reviews your case together and recommends a plan.', clinician: 'Multidisciplinary review for every new case; reassess at progression.', questions: ['Has a liver tumor board reviewed my case?', 'What are all my options, including trials?'] },
  { id: 'curative', subtypes: [...ALL], title: 'Treatment aiming for cure', plain: 'Surgery, ablation or transplant can cure early cancers.', plainBy: { HCC: 'When the cancer is found early, surgery, ablation (destroying the tumor with heat) or a liver transplant can cure it.', iCCA: 'Surgery to remove the tumor offers the best chance of cure. Afterwards, six months of chemotherapy pills (capecitabine) is usually recommended.', HB: 'Most children have chemotherapy first to shrink the tumor, then surgery. If the tumor cannot be removed, a liver transplant can still cure it. Most children are cured.' }, clinician: 'HCC: resection/ablation/transplant (Milan, downstaging). iCCA: resection + adjuvant capecitabine. HB: cisplatin-based + resection/transplant, sodium thiosulfate otoprotection.', questions: ['Is the goal cure or control?', 'What happens after surgery — more treatment or watching?'] },
  { id: 'locoregional', subtypes: ['HCC'], title: 'Treating the tumor inside the liver', plain: 'Procedures like TACE or radioembolization send treatment straight into the tumor through its blood supply.', clinician: 'TACE standard for BCLC B; TACE + systemic combinations improved PFS but not OS (EMERALD-1, LEAP-012).', questions: ['Am I a candidate for TACE or radioembolization?', 'Could this make me eligible for transplant later?'] },
  { id: 'systemic', subtypes: ['HCC', 'iCCA'], title: 'Medicines for advanced cancer', plain: 'Medicines that treat the whole body are used when cancer has spread or cannot be removed.', plainBy: { HCC: 'Immunotherapy combinations are now the first choice for many people with advanced liver-cell cancer, if the liver works well enough. Pills such as lenvatinib or sorafenib are options too.', iCCA: 'Chemotherapy plus immunotherapy is the usual first treatment for advanced bile-duct cancer. If the tumor has a matching gene change, a targeted pill may come next.' }, clinician: 'HCC 1L: atezo-bev, STRIDE, nivo-ipi (Child-Pugh A); TKIs if IO unsuitable. BTC 1L: GemCis + durvalumab or pembrolizumab; 2L by biomarker.', questions: ['Which first treatment fits my liver function and health?', 'Do I need an endoscopy for varices before starting?', 'Which side effects should make me call right away?'] },
  { id: 'trials', subtypes: [...ALL], title: 'Clinical trials', plain: 'Trials test new treatments and can give access to medicines before approval. Ask at every step whether one fits you.', clinician: 'Use the workbench Trials section filtered by gene, drug and subtype.', questions: ['Is there a clinical trial I could join?', 'Where is the nearest center running it?'] },
  { id: 'followup', subtypes: [...ALL], title: 'Follow-up and living well', plain: 'Regular scans and blood tests watch for any return of cancer. Care for the liver, nutrition, mood and family life is part of treatment too.', clinician: 'Imaging + AFP surveillance after curative therapy; manage underlying liver disease (antivirals, alcohol cessation, metabolic risk); survivorship and palliative care integration.', questions: ['How often will I have scans after treatment?', 'Who do I call between visits?'] },
];

