export const GLOSSARY: GlossaryItem[] = [
  { term: 'AFP (alpha-fetoprotein)', def: 'A protein measured in the blood. High levels can be a sign of liver cancer or hepatoblastoma and help track treatment.' },
  { term: 'Ablation', def: 'Destroying a small tumor with heat (or cold) through a needle, without open surgery.' },
  { term: 'BCLC stage', def: 'The Barcelona system for staging liver cell cancer (0, A, B, C, D). It considers the tumor, liver function and general health.' },
  { term: 'Biomarker', def: 'Something measured in blood or the tumor that helps choose or predict treatment, like AFP or an FGFR2 fusion.' },
  { term: 'Child-Pugh score', def: 'A score (A, B or C) for how well the liver is working. Many medicines require Child-Pugh A.' },
  { term: 'Cholangiocarcinoma', def: 'Cancer of the bile ducts. “Intrahepatic” means it starts in bile ducts inside the liver.' },
  { term: 'Cirrhosis', def: 'Long-term scarring of the liver. It raises the risk of liver cancer.' },
  { term: 'Clinical trial', def: 'A research study that tests whether a new treatment is safe and works better.' },
  { term: 'Complete response', def: 'No cancer can be seen on scans after treatment. It does not always mean cure.' },
  { term: 'Gene fusion', def: 'When two genes join by mistake, making an abnormal signal that can drive cancer. Some fusions (like FGFR2) have matched medicines.' },
  { term: 'Hepatoblastoma', def: 'A rare liver cancer of young children, usually under age 3. Most children are cured.' },
  { term: 'Hepatocellular carcinoma (HCC)', def: 'The most common liver cancer in adults. It starts in the main liver cells.' },
  { term: 'Immunotherapy', def: 'Medicines that help your immune system recognize and attack cancer.' },
  { term: 'Median survival', def: 'The time at which half the people in a study are still alive. Many people live longer than the median.' },
  { term: 'NGS (next-generation sequencing)', def: 'A lab test that reads many tumor genes at once to look for changes with matched treatments.' },
  { term: 'PRETEXT', def: 'The staging system for hepatoblastoma, based on which parts of the liver the tumor involves.' },
  { term: 'TACE', def: 'Chemoembolization: chemotherapy and tiny particles are sent into the artery feeding the tumor to starve it.' },
  { term: 'Targeted therapy', def: 'A medicine aimed at a specific change in the tumor, such as FGFR2, IDH1, HER2 or BRAF.' },
  { term: 'Transplant (liver)', def: 'Replacing the diseased liver with a healthy donor liver. It can cure some early liver cancers.' },
  { term: 'Varices', def: 'Swollen veins in the food pipe or stomach caused by liver scarring. They are checked before some cancer medicines.' },
];

